def apply_triangle_transform(triangle):
    """Apply triangle->rectangle transformation to grid"""
    tl, tr, bl = triangle  # Three corners of right triangle

    # Create output from input
    output = [[grid[r][c] for c in range(14)] for r in range(24)]

    rmin, rmax = min(tl[0], tr[0]), max(tl[0], tr[0])
    cmin, cmax = min(tl[1], tr[1]), max(tl[1], tr[1])

    # Clear the rectangle interior first
    for r in range(rmin, rmax + 1):
        for c in range(cmin, cmax + 1):
            if r != rmin and r != rmax and c != cmin and c != cmax:
                output[r][c] = 0

    # Draw boundary with 2s
    for r in range(rmin, rmax + 1):
        for c in range(cmin, cmax + 1):
            if r == rmin or r == rmax or c == cmin or c == cmax:
