def find_all_triangle_rects():
    """Find all sets of three markers forming right-triangle corners"""
    rect_sets = []

    # For each pair of points on same row
    for row_num in range(24):
        row_eights = [(row_num, c) for c in range(14) if grid[row_num][c] == 8]

        # Check pairs on this row as potential horizontal edge
        for i, p_left in enumerate(row_eights):
            for p_right in row_eights[i+1:]:
                left_col = p_left[1]

                # Find any point vertically aligned below LEFT endpoint
                for r_below in range(p_left[0] + 1, 24):
                    if (r_below, left_col) in eights_set:
                        p_bottom = (r_below, left_col)

                        # Form complete rectangle by finding missing corner
                        top_left = p_left
                        top_right = p_right
                        bottom_left = p_bottom

                        # Missing corner would be at (bottom_left[0], top_right[1])
                        missing = (r_below, p_right[1])

                        # Only add if missing corner ALSO exists (complete rectangle)
                        if missing in eights_set:
                            rect_corners = sorted([top_left, top_right, bottom_left, missing])
                            if rect_corners not in rect_sets:
                                rect_sets.append(rect_corners)

    return rect_sets

